const listVendors = `-- name: ListVendors :many

SELECT v.id, v.organization_id, v.kind, v.name, v.tax_code, v.website, v.support_phone, v.support_email, v.support_portal, v.notes, v.created_at, v.updated_at, v.version, v.deleted_at,
       (SELECT count(*) FROM vendor_contacts c WHERE c.vendor_id = v.id AND c.organization_id = v.organization_id)::bigint AS contact_count,
       (SELECT count(*) FROM contracts k WHERE k.vendor_id = v.id AND k.organization_id = v.organization_id AND k.deleted_at IS NULL)::bigint AS contract_count,
       (SELECT min(k.end_date) FROM contracts k
         WHERE k.vendor_id = v.id AND k.deleted_at IS NULL AND k.end_date >= $1::date)::date AS next_end
FROM vendors v
WHERE v.organization_id = $2 AND v.deleted_at IS NULL
  AND ($3::text = '' OR v.kind = $3)
  AND ($4::text = '' OR v.name ILIKE '%' || $4 || '%' OR v.tax_code ILIKE '%' || $4 || '%')
ORDER BY lower(v.name)
`

type ListVendorsParams struct {
	Today          pgtype.Date
	OrganizationID pgtype.UUID
	Kind           string
	Q              string
}

type ListVendorsRow struct {
	ID             pgtype.UUID
	OrganizationID pgtype.UUID
	Kind           string
	Name           string
	TaxCode        string
	Website        string
	SupportPhone   string
	SupportEmail   string
	SupportPortal  string
	Notes          string
	CreatedAt      pgtype.Timestamptz
	UpdatedAt      pgtype.Timestamptz
	Version        int32
	DeletedAt      pgtype.Timestamptz
	ContactCount   int64
	ContractCount  int64
	NextEnd        pgtype.Date
}

// Vendors, contacts, contracts, contract files (P2-04, ADR-044). Every query is scoped to @organization_id.
func (q *Queries) ListVendors(ctx context.Context, arg ListVendorsParams) ([]ListVendorsRow, error) {
	rows, err := q.db.Query(ctx, listVendors,
		arg.Today,
		arg.OrganizationID,
		arg.Kind,
		arg.Q,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListVendorsRow
	for rows.Next() {
		var i ListVendorsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrganizationID,
			&i.Kind,
			&i.Name,
			&i.TaxCode,
			&i.Website,
			&i.SupportPhone,
			&i.SupportEmail,
			&i.SupportPortal,
			&i.Notes,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Version,
			&i.DeletedAt,
			&i.ContactCount,
			&i.ContractCount,
			&i.NextEnd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

